  "inlineSchema": "// =====================================================================\n//  CONTROL schema: the ONLY tables in the main database (DATABASE_URL).\n//  It holds the super admin and the lab (admin) accounts created by the super\n//  admin. Patients, bills, tests, employees... live in each lab's own database\n//  (see prisma/schema.prisma).\n//\n//  Commands (always pass --schema):\n//      npx prisma migrate dev --schema prisma/control/schema.prisma --name <name>\n//      npx prisma migrate deploy --schema prisma/control/schema.prisma\n//      npx prisma generate --schema prisma/control/schema.prisma\n// =====================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/control\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// Platform owner (you). Signs in on the Super admin panel.\nmodel SuperAdmin {\n  id           Int      @id @default(autoincrement())\n  name         String   @db.VarChar(255)\n  email        String   @unique @db.VarChar(190)\n  passwordHash String   @map(\"password_hash\") @db.VarChar(255)\n  active       Boolean  @default(true)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"super_admins\")\n}\n\n/// One lab = one admin account with its own database.\nmodel Tenant {\n  id                Int                @id @default(autoincrement())\n  labName           String             @map(\"lab_name\") @db.VarChar(255)\n  adminName         String             @map(\"admin_name\") @db.VarChar(255)\n  adminEmail        String             @unique @map(\"admin_email\") @db.VarChar(190)\n  passwordHash      String             @map(\"password_hash\") @db.VarChar(255)\n  /// The lab's database URL, encrypted (AES-256-GCM) with TENANT_SECRET.\n  dbUrlEncrypted    String?            @map(\"db_url_encrypted\") @db.Text\n  /// host:port/database, safe to show in the panel.\n  dbHost            String?            @map(\"db_host\") @db.VarChar(255)\n  /// Hash of host:port/database, so two labs can never share one database.\n  dbFingerprint     String?            @unique @map(\"db_fingerprint\") @db.Char(64)\n  connectedAt       DateTime?          @map(\"connected_at\")\n  lastLoginAt       DateTime?          @map(\"last_login_at\")\n  failedLoginCount  Int                @default(0) @map(\"failed_login_count\")\n  lockedUntil       DateTime?          @map(\"locked_until\")\n  active            Boolean            @default(true)\n  createdAt         DateTime           @default(now()) @map(\"created_at\")\n  updatedAt         DateTime           @updatedAt @map(\"updated_at\")\n  users             TenantUser[]\n  sessions          TenantSession[]\n  notificationReads NotificationRead[]\n\n  @@map(\"tenants\")\n}\n\n/// Which lab an e-mail address belongs to, so employees sign in with just e-mail and password.\nmodel TenantUser {\n  email    String @id @db.VarChar(190)\n  tenantId Int    @map(\"tenant_id\")\n  tenant   Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@map(\"tenant_users\")\n}\n\n/// Which lab a signed-in token belongs to (the token itself is never stored, only its hash).\nmodel TenantSession {\n  tokenHash String   @id @map(\"token_hash\") @db.Char(64)\n  tenantId  Int      @map(\"tenant_id\")\n  expiresAt DateTime @map(\"expires_at\")\n  tenant    Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([expiresAt])\n  @@map(\"tenant_sessions\")\n}\n\nmodel Notification {\n  id        Int                @id @default(autoincrement())\n  title     String             @db.VarChar(200)\n  message   String             @db.Text\n  createdAt DateTime           @default(now()) @map(\"created_at\")\n  expiresAt DateTime?          @map(\"expires_at\")\n  active    Boolean            @default(true)\n  reads     NotificationRead[]\n\n  @@index([active, createdAt])\n  @@map(\"notifications\")\n}\n\nmodel NotificationRead {\n  id             Int      @id @default(autoincrement())\n  notificationId Int      @map(\"notification_id\")\n  tenantId       Int      @map(\"tenant_id\")\n  userId         Int      @map(\"user_id\")\n  readAt         DateTime @default(now()) @map(\"read_at\")\n\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  tenant       Tenant       @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, tenantId, userId])\n  @@index([tenantId, userId])\n  @@map(\"notification_reads\")\n}\n",
